// test_gp.sio — Tests for Gaussian process regression module
//
// Self-contained test suite for kernels (RBF, Matern 3/2, periodic),
// Cholesky factorization/solve, GP train/predict, log marginal likelihood,
// and posterior variance behaviour. All helpers inlined since tests cannot import.
//
// References:
//   Rasmussen & Williams (2006): "Gaussian Processes for Machine Learning"
//   Bishop (2006): "Pattern Recognition and Machine Learning" Ch. 6

// ============================================================================
// PURE MATH HELPERS (must precede callers)
// ============================================================================

fn gp_h_abs(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }
fn gp_h_max(a: f64, b: f64) -> f64 { if a > b { a } else { b } }
fn gp_h_min(a: f64, b: f64) -> f64 { if a < b { a } else { b } }

fn gp_h_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 25 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn gp_h_exp(x: f64) -> f64 with Mut, Div, Panic {
    let ln2 = 0.6931471805599453
    let inv_ln2 = 1.4426950408889634

    if x > 709.0 { return 1.0e308 }
    if x < -709.0 { return 0.0 }

    var k_f = x * inv_ln2
    var k: i64 = 0
    if k_f >= 0.0 { k = (k_f + 0.5) as i64 } else { k = (k_f - 0.5) as i64 }

    let r = x - (k as f64) * ln2

    var sum = 1.0
    var term = 1.0
    var n = 1
    while n <= 20 {
        term = term * r / (n as f64)
        sum = sum + term
        n = n + 1
    }

    var result = sum
    var kabs = k
    if kabs < 0 { kabs = 0 - kabs }
    var pow2 = 2.0
    var ka = kabs
    var acc = 1.0
    while ka > 0 {
        if ka - (ka / 2) * 2 != 0 { acc = acc * pow2 }
        pow2 = pow2 * pow2
        ka = ka / 2
    }
    if k >= 0 { result = result * acc } else { result = result / acc }
    result
}

fn gp_h_ln(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return -1.0e30 }
    if x == 1.0 { return 0.0 }

    var y = 0.0
    var a = x
    let ln2 = 0.6931471805599453
    while a > 2.0 { a = a * 0.5; y = y + ln2 }
    while a < 0.5 { a = a * 2.0; y = y - ln2 }

    let t = (a - 1.0) / (a + 1.0)
    let t2 = t * t
    var sum = t
    var power = t
    var n = 1
    while n <= 30 {
        power = power * t2
        sum = sum + power / (2.0 * (n as f64) + 1.0)
        n = n + 1
    }
    y + 2.0 * sum
}

fn gp_h_sin(x: f64) -> f64 with Mut, Div, Panic {
    var a = x
    let tp = 6.28318530717958647692
    while a >= tp { a = a - tp }
    while a < 0.0 { a = a + tp }
    if a > 3.14159265358979323846 { a = a - tp }
    let a2 = a * a
    var sum = a
    var term = a
    var n = 1
    while n < 18 {
        term = 0.0 - term * a2 / ((2 * n) * (2 * n + 1)) as f64
        sum = sum + term
        n = n + 1
    }
    sum
}

fn gp_h_cos(x: f64) -> f64 with Mut, Div, Panic {
    gp_h_sin(x + 1.57079632679489661923)
}

fn gp_h_pi() -> f64 { 3.14159265358979323846 }

fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
    gp_h_abs(a - b) < tol
}

// ============================================================================
// STRUCTS
// ============================================================================

struct GPData {
    x_train: [f64; 128],
    y_train: [f64; 128],
    n_train: i32,
    noise_var: f64
}

struct GPHyper {
    signal_var: f64,
    length_scale: f64,
    noise_var: f64,
    kernel_type: i32,
    extra_param: f64
}

struct GPModel {
    L: [f64; 4096],
    alpha: [f64; 128],
    mx: [f64; 128],
    my: [f64; 128],
    mn: i32,
    hyper: GPHyper,
    log_ml: f64
}

struct GPPrediction {
    mean: f64,
    variance: f64,
    std_dev: f64
}

// ============================================================================
// KERNEL FUNCTIONS
// ============================================================================

fn kernel_rbf(x: f64, y: f64, hyper: &GPHyper) -> f64 with Mut, Div, Panic {
    let d = x - y
    let l = hyper.length_scale
    hyper.signal_var * gp_h_exp(0.0 - 0.5 * d * d / (l * l))
}

fn kernel_matern32(x: f64, y: f64, hyper: &GPHyper) -> f64 with Mut, Div, Panic {
    let r = gp_h_abs(x - y)
    let l = hyper.length_scale
    let sqrt3 = 1.7320508075688772
    let z = sqrt3 * r / l
    hyper.signal_var * (1.0 + z) * gp_h_exp(0.0 - z)
}

fn kernel_matern52(x: f64, y: f64, hyper: &GPHyper) -> f64 with Mut, Div, Panic {
    let r = gp_h_abs(x - y)
    let l = hyper.length_scale
    let sqrt5 = 2.2360679774997896
    let z = sqrt5 * r / l
    let z2 = 5.0 * r * r / (3.0 * l * l)
    hyper.signal_var * (1.0 + z + z2) * gp_h_exp(0.0 - z)
}

fn kernel_periodic(x: f64, y: f64, hyper: &GPHyper) -> f64 with Mut, Div, Panic {
    let r = gp_h_abs(x - y)
    let l = hyper.length_scale
    let p = hyper.extra_param
    let s = gp_h_sin(gp_h_pi() * r / p)
    hyper.signal_var * gp_h_exp(0.0 - 2.0 * s * s / (l * l))
}

fn kernel_eval(x: f64, y: f64, hyper: &GPHyper) -> f64 with Mut, Div, Panic {
    if hyper.kernel_type == 0 { return kernel_rbf(x, y, hyper) }
    if hyper.kernel_type == 1 { return kernel_matern32(x, y, hyper) }
    if hyper.kernel_type == 2 { return kernel_matern52(x, y, hyper) }
    if hyper.kernel_type == 3 { return kernel_periodic(x, y, hyper) }
    kernel_rbf(x, y, hyper)
}

// ============================================================================
// CHOLESKY FACTORIZATION AND SOLVE
// ============================================================================

fn gp_cholesky(K: &[f64; 4096], n: i32, L: &![f64; 4096]) -> bool with Mut, Div, Panic {
    var idx = 0
    while idx < n * n { L[idx] = 0.0; idx = idx + 1 }

    var j = 0
    while j < n {
        var sum_diag = 0.0
        var k = 0
        while k < j {
            let ljk = L[j * n + k]
            sum_diag = sum_diag + ljk * ljk
            k = k + 1
        }
        let diag_val = K[j * n + j] - sum_diag
        if diag_val <= 0.0 { return false }
        L[j * n + j] = gp_h_sqrt(diag_val)

        var i = j + 1
        while i < n {
            var sum_off = 0.0
            k = 0
            while k < j {
                sum_off = sum_off + L[i * n + k] * L[j * n + k]
                k = k + 1
            }
            L[i * n + j] = (K[i * n + j] - sum_off) / L[j * n + j]
            i = i + 1
        }
        j = j + 1
    }
    true
}

fn gp_cholesky_solve(L: &[f64; 4096], b: &[f64; 128], n: i32, x: &![f64; 128]) with Mut, Div, Panic {
    var z: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < i {
            sum = sum + L[i * n + j] * z[j]
            j = j + 1
        }
        z[i] = (b[i] - sum) / L[i * n + i]
        i = i + 1
    }

    i = n - 1
    while i >= 0 {
        var sum = 0.0
        var j = i + 1
        while j < n {
            sum = sum + L[j * n + i] * x[j]
            j = j + 1
        }
        x[i] = (z[i] - sum) / L[i * n + i]
        i = i - 1
    }
}

fn gp_forward_solve(L: &[f64; 4096], b: &[f64; 128], n: i32, v: &![f64; 128]) with Mut, Div, Panic {
    var i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < i {
            sum = sum + L[i * n + j] * v[j]
            j = j + 1
        }
        v[i] = (b[i] - sum) / L[i * n + i]
        i = i + 1
    }
}

// ============================================================================
// GP TRAINING
// ============================================================================

fn gp_train(data: &GPData, hyper: &GPHyper, model: &!GPModel) -> bool with Mut, Div, Panic {
    let n = data.n_train

    var i = 0
    while i < n {
        model.mx[i] = data.x_train[i]
        model.my[i] = data.y_train[i]
        i = i + 1
    }
    model.mn = n
    var local_hyper: GPHyper = GPHyper {
        signal_var: hyper.signal_var,
        length_scale: hyper.length_scale,
        noise_var: hyper.noise_var,
        kernel_type: hyper.kernel_type,
        extra_param: hyper.extra_param
    }
    model.hyper = local_hyper

    var K: [f64; 4096] = [0.0; 4096]
    i = 0
    while i < n {
        var j = 0
        while j < n {
            let kval = kernel_eval(data.x_train[i], data.x_train[j], hyper)
            if i == j {
                K[i * n + j] = kval + hyper.noise_var
            } else {
                K[i * n + j] = kval
            }
            j = j + 1
        }
        i = i + 1
    }

    var local_L: [f64; 4096] = [0.0; 4096]
    let ok = gp_cholesky(&K, n, &!local_L)
    if !ok { return false }
    var li: i32 = 0
    while li < n * n { model.L[li] = local_L[li]; li = li + 1 }

    var local_alpha: [f64; 128] = [0.0; 128]
    gp_cholesky_solve(&local_L, data.y_train, n, &!local_alpha)
    var ai: i32 = 0
    while ai < n { model.alpha[ai] = local_alpha[ai]; ai = ai + 1 }

    var data_fit = 0.0
    i = 0
    while i < n {
        data_fit = data_fit + data.y_train[i] * model.alpha[i]
        i = i + 1
    }
    data_fit = 0.0 - 0.5 * data_fit

    var complexity = 0.0
    i = 0
    while i < n {
        complexity = complexity + gp_h_ln(model.L[i * n + i])
        i = i + 1
    }
    complexity = 0.0 - complexity

    let norm_const = 0.0 - 0.5 * (n as f64) * gp_h_ln(2.0 * gp_h_pi())

    model.log_ml = data_fit + complexity + norm_const
    true
}

// ============================================================================
// GP PREDICTION
// ============================================================================

fn gp_predict(model: &GPModel, x_star: f64, pred: &!GPPrediction) with Mut, Div, Panic {
    let n = model.mn

    var k_star: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        k_star[i] = kernel_eval(x_star, model.mx[i], model.hyper)
        i = i + 1
    }

    var mean = 0.0
    i = 0
    while i < n {
        mean = mean + k_star[i] * model.alpha[i]
        i = i + 1
    }
    pred.mean = mean

    var v: [f64; 128] = [0.0; 128]
    gp_forward_solve(model.L, &k_star, n, &!v)

    let k_ss = kernel_eval(x_star, x_star, model.hyper)
    var v_dot_v = 0.0
    i = 0
    while i < n {
        v_dot_v = v_dot_v + v[i] * v[i]
        i = i + 1
    }
    var variance = k_ss - v_dot_v
    if variance < 0.0 { variance = 0.0 }
    pred.variance = variance
    pred.std_dev = gp_h_sqrt(variance)
}

fn gp_log_marginal(model: &GPModel) -> f64 {
    model.log_ml
}

// ============================================================================
// HELPER: build training data from x^2 (5 points)
