fn build_quad_data(data: &!GPData) with Mut, Panic {
    // 5 training points: x in {0.0, 1.0, 2.0, 3.0, 4.0}, y = x^2
    data.n_train = 5
    data.noise_var = 0.01

    data.x_train[0] = 0.0
    data.x_train[1] = 1.0
    data.x_train[2] = 2.0
    data.x_train[3] = 3.0
    data.x_train[4] = 4.0

    data.y_train[0] = 0.0
    data.y_train[1] = 1.0
    data.y_train[2] = 4.0
    data.y_train[3] = 9.0
    data.y_train[4] = 16.0
}

fn make_rbf_hyper() -> GPHyper {
    GPHyper {
        signal_var: 1.0,
        length_scale: 1.0,
        noise_var: 0.01,
        kernel_type: 0,
        extra_param: 0.0
    }
}

fn make_zero_model() -> GPModel {
    GPModel {
        L: [0.0; 4096],
        alpha: [0.0; 128],
        mx: [0.0; 128],
        my: [0.0; 128],
        mn: 0,
        hyper: GPHyper {
            signal_var: 0.0,
            length_scale: 0.0,
            noise_var: 0.0,
            kernel_type: 0,
            extra_param: 0.0
        },
        log_ml: 0.0
    }
}

